#!/usr/bin/env python3
"""Offline bind→node and source-branch evidence for measured original/final deltas."""
import pathlib,json,hashlib
H=pathlib.Path(__file__).resolve().parent;REPRO=H.parents[3];paths={'ad469':H/'census/20261020T232351Z-baseline','final32':H/'census/20261020T233449Z-final'};data={k:json.loads((p/'sql-census.json').read_text())for k,p in paths.items()};out={'source_census_paths':{k:str(v)for k,v in paths.items()},'representative':'second warmed measured request; same actor/target from fresh matching clones','operations':{}}
for op in data['ad469']:
 old=data['ad469'][op]['requests'][1];new=data['final32'][op]['requests'][1];a=[x.get('parameters')for x in old['operations']if x['category']=='hydration.full_anchor'];b=[x.get('parameters')for x in new['operations']if x['category']=='hydration.full_anchor'];out['operations'][op]={'original_count':old['executed_commands'],'final_count':new['executed_commands'],'original_hydration_parameters':a,'final_hydration_parameters':b,'removed_hydration_parameters':[v for v in a if v not in b],'removed_categories':{k:old['categories'][k]-new['categories'].get(k,0)for k in old['categories']if old['categories'][k]>new['categories'].get(k,0)}}
zero='00000000-0000-0000-0000-000000000000';tsv=H.parent/'fixtures/t20/anchors.tsv';line=next(s for s in tsv.open()if s.startswith(zero+'\t'));fields=line.rstrip('\n').split('\t');assert fields[1:3]==['NodeAnchor','Root'];out['removed_UUID_class']={'uuid':zero,'kind':fields[1],'arch_type':fields[2],'arch_module':fields[3],'source':str(tsv),'source_row_sha256':hashlib.sha256(line.encode()).hexdigest(),'runtime_constant':'Con.SUPER_ROOT_UUID'}
out['source_evidence']=[]
for label,source in [('ad469',REPRO/'runtime/ad469-source/jac'),('final32',REPRO.parent/'jac-db/jac')]:
 f=source/'jaclang/runtimelib/impl/context.impl.jac';lines=f.read_text().splitlines();out['source_evidence'].append({'runtime':label,'file':str(f),'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'lazy_default_lines':[(i+1,s)for i,s in enumerate(lines)if "os.environ.get('JAC_LAZY_TXN'"in s],'root_resolve_definition_line':next(i+1 for i,s in enumerate(lines)if'impl ExecutionContext._resolve_roots'in s),'user_root_definition_line':next(i+1 for i,s in enumerate(lines)if'impl ExecutionContext.aset_user_root'in s),'launch_LAZY_TXN':json.loads((paths[label]/'launch.json').read_text())['environment'].get('JAC_LAZY_TXN','unset')})
out['interpretation']='The removed bound UUID is the super-root. With JAC_LAZY_TXN unset, ad469 selects its eager default and final32 selects its lazy default. _resolve_roots uses an ID-only stub in the lazy branch; aset_user_root similarly defers the user-root read. The traces retain the eventual actor-root hydration and remove the super-root hydration. Feed/page additionally execute one transaction instead of two. These are SQL-count and source-branch observations; latency uses separate quiet measurements.'
(H/'original-final-operation-delta.json').write_text(json.dumps(out,indent=2)+'\n');md=['# littleX original/final SQL delta','',out['interpretation'],'','| Operation | ad469 commands | Final32 commands | Removed super-root hydration |','|---|---:|---:|---:|']
for op,r in out['operations'].items():md.append('| %s | %s | %s | %s |'%(op,r['original_count'],r['final_count'],len(r['removed_hydration_parameters'])))
md+=['','`original-final-operation-delta.json` retains exact UUID bindings, node-type evidence, source SHA256s and branch locations. The source log directories retain all three repetitions, including first-repetition cache/setup variation.']
(H/'original-final-operation-delta.md').write_text('\n'.join(md)+'\n')
